import {memo} from 'react'

import useMyId from '../../../../../../hooks/useMyId'
import type {Investigation} from '../../../../../../types'
import {InvestigationStates} from '../../../../../../types'

import styles from './InvestigationAssigneeName.module.css'

type Props = {
  investigationInCurrentScope: Investigation
}

function InvestigationAssigneeName({investigationInCurrentScope}: Props) {
  const currentUserId = useMyId()
  const {state} = investigationInCurrentScope ?? {}
  const isAssignedToCurrentUser = investigationInCurrentScope.assignee.id === currentUserId
  const name =
    investigationInCurrentScope.assignee.name === undefined
      ? investigationInCurrentScope.assignee.username
      : investigationInCurrentScope.assignee.name
  return (
    <span className={styles.assigneeBlock}>
      {state === InvestigationStates.FIXED ? (
        <span>{`Fixed by ${name}`}</span>
      ) : investigationInCurrentScope.assignment.user == null ? (
        <span>
          <span>{'to '}</span>
          <span
            className={isAssignedToCurrentUser ? styles.assigneeToCurrentUser : styles.assignee}
          >
            {name}
          </span>
          <span>{' automatically'}</span>
        </span>
      ) : investigationInCurrentScope.assignee.id ===
        investigationInCurrentScope.assignment.user?.id ? (
        <span>
          <span>{'Self-assigned to '}</span>
          <span
            className={isAssignedToCurrentUser ? styles.assigneeToCurrentUser : styles.assignee}
          >
            {name}
          </span>
        </span>
      ) : (
        <span>
          <span>{'to '}</span>
          <span
            className={isAssignedToCurrentUser ? styles.assigneeToCurrentUser : styles.assignee}
          >
            {name}
          </span>
          <span>{` by ${
            investigationInCurrentScope.assignment.user?.name == null
              ? investigationInCurrentScope.assignment.user?.username
              : investigationInCurrentScope.assignment.user?.name
          }`}</span>
        </span>
      )}
    </span>
  )
}

export default memo(InvestigationAssigneeName)
