import type {KeyValue, WritableKeyValue} from '@jetbrains/teamcity-ui/dist/utils'

import type {BuildId, TestsTreeNodeId, ProjectId} from '../../../../types'
import {ROOT_PROJECT_ID, stringifyId} from '../../../../types'
import type {Node, NodeValue} from '../../../common/Tree/Tree.types'
import type {TestOccurrencesTreeLeaf, TestOccurrencesTreeNode} from '../Tests.types'
import {TreeEntityType} from '../Tests.types'

import type {AdvancedNode} from './TestsTree.types'
import TestsTreeLeaf from './TestsTreeLeaf/TestsTreeLeaf'
import TestsTreeLeafDetails from './TestsTreeLeafDetails/TestsTreeLeafDetails'
import TestsTreeNode from './TestsTreeNode/TestsTreeNode'
import TestsTreeNodeFooter from './TestsTreeNodeFooter/TestsTreeNodeFooter'

export const getTestsLocator = ({
  baseLocator,
  projectId,
}: {
  baseLocator?: string
  projectId?: ProjectId
}): string => {
  const projectLocator =
    projectId != null
      ? `affectedProject:${stringifyId(projectId)},currentlyFailing:true,currentlyInvestigated:true`
      : ''
  return [baseLocator, projectLocator].filter(Boolean).join(',')
}
const config: Record<TreeEntityType, TreeEntityType[]> = {
  [TreeEntityType.PROJECT]: [
    TreeEntityType.PROJECT,
    TreeEntityType.BUILD_TYPE,
    TreeEntityType.BUILD,
  ],
  [TreeEntityType.BUILD_TYPE]: [TreeEntityType.BUILD_TYPE, TreeEntityType.BUILD],
  [TreeEntityType.SPLIT_BUILD]: [TreeEntityType.BUILD],
  [TreeEntityType.BUILD]: [],
  [TreeEntityType.SUITE]: [TreeEntityType.PACKAGE, TreeEntityType.CLASS],
  [TreeEntityType.PACKAGE]: [TreeEntityType.CLASS],
  [TreeEntityType.CLASS]: [],
}

export const generateTestsTree = (
  dataNodes: ReadonlyArray<TestOccurrencesTreeNode>,
  dataLeavesHash: KeyValue<TestsTreeNodeId, TestOccurrencesTreeLeaf>,
  treeLocator: string,
  buildId: BuildId | undefined,
  isSimple?: boolean,
): Node | null => {
  let root = null
  let buildsCount = 0
  let hasCurrentBuild = false
  const map: WritableKeyValue<string, number> = {}
  const advancedDataNodeHash: WritableKeyValue<NodeValue, AdvancedNode> = {}

  if (dataNodes.length === 0) {
    return null
  }

  const nodes: ReadonlyArray<Node> = dataNodes.map((dataNode, index) => {
    const {id, name, type} = dataNode
    map[id] = index
    advancedDataNodeHash[id] = {
      ...dataNode,
      abstractParents: [],
      allParents: [],
    }
    if (type === TreeEntityType.BUILD) {
      hasCurrentBuild = name === stringifyId(buildId)
      buildsCount += 1
    }
    return {
      value: id,
      label: name,
      children: [], // Default value
    }
  })

  const simplifyTree = isSimple || (buildsCount === 1 && hasCurrentBuild)

  for (let index = 0; index < dataNodes.length; index++) {
    const {parentId, type} = dataNodes[index]
    if (
      !simplifyTree ||
      (simplifyTree && type !== TreeEntityType.PROJECT && type !== TreeEntityType.BUILD_TYPE)
    ) {
      const node = nodes[index]
      const packageIndex = map[stringifyId(parentId)]

      if (parentId == null || (simplifyTree && type === TreeEntityType.BUILD)) {
        root = node
      } else {
        const children = packageIndex != null ? nodes[packageIndex].children : null
        if (Array.isArray(children)) {
          children.push(node)
        }
      }
    }
  }

  const findAllParents = (node: Node): void => {
    if (node.children != null) {
      const advancedDataNode = advancedDataNodeHash[node.value]
      if (advancedDataNode == null) {
        return
      }

      const {allParents = [], ...abstractNode} = advancedDataNode

      node.children.forEach(child => {
        const childNode = advancedDataNodeHash[child.value]
        if (childNode != null) {
          childNode.allParents = [...allParents, abstractNode]
          findAllParents(child)
        }
      })
    }
  }

  if (root != null) {
    findAllParents(root)
  }

  const findNonAbstractChild = (node: Node): Node => {
    if (node.children != null) {
      const child = node.children[0]
      const advancedDataNode = advancedDataNodeHash[node.value]

      if (advancedDataNode == null) {
        return node
      }

      const {abstractParents = [], ...abstractNode} = advancedDataNode
      const childNode = advancedDataNodeHash[child.value]

      if (childNode != null && config[abstractNode.type].includes(childNode.type)) {
        childNode.abstractParents = [...abstractParents, abstractNode]
        return child.children?.length === 1 ? findNonAbstractChild(child) : child
      }
    }

    return node
  }

  const removeAbstractParents = (children: Node[] = []) => {
    for (let i = 0; i < children.length; i++) {
      const node = children[i]

      if (node.children != null && node.children.length === 1) {
        children.splice(i, 1, findNonAbstractChild(node))
      }

      removeAbstractParents(children[i].children)
    }
  }

  const addComponents = (parent: Node) => {
    const {children} = parent

    if (children == null) {
      return
    }

    for (let i = 0; i < children.length; i++) {
      const advancedDataNode = advancedDataNodeHash[children[i].value]

      if (advancedDataNode != null) {
        const {type, id, childrenCount, testCounters, allParents = []} = advancedDataNode

        if (type === TreeEntityType.CLASS) {
          const testOccurrences = dataLeavesHash[id]?.testOccurrences?.testOccurrence ?? []
          children[i].children = testOccurrences.map(testOccurrence => ({
            value: stringifyId(testOccurrence.id),
            label: testOccurrence.name,
            component: <TestsTreeLeaf testOccurrence={testOccurrence} />,

            detailsComponent: <TestsTreeLeafDetails testOccurrence={testOccurrence} />,
          }))
        }

        children[i] = {
          ...children[i],
          component: <TestsTreeNode dataNode={advancedDataNode} buildId={buildId} />,
          footerComponent: (
            <TestsTreeNodeFooter
              node={children[i]}
              type={type}
              childrenCount={childrenCount}
              testCounters={testCounters}
              depth={allParents.length}
              treeLocator={treeLocator}
            />
          ),
        }

        if (advancedDataNode.type !== TreeEntityType.CLASS) {
          addComponents(children[i])
        }
      }
    }
  }

  removeAbstractParents(root?.children)
  if (root) {
    const advancedDataNode = advancedDataNodeHash[root.value]

    if (advancedDataNode != null) {
      const {type, childrenCount, testCounters, allParents = []} = advancedDataNode
      root.footerComponent = (
        <TestsTreeNodeFooter
          node={root}
          type={type}
          childrenCount={childrenCount}
          testCounters={testCounters}
          depth={allParents.length}
          treeLocator={treeLocator}
        />
      )
    }

    addComponents(root)
  }

  return root
}

export const getRootTestCounters = (
  nodes: ReadonlyArray<TestOccurrencesTreeNode> | undefined | null,
) => nodes?.find(node => node.name === ROOT_PROJECT_ID)?.testCounters
