import {memo, useCallback, useContext, useMemo} from 'react'

import EntityPath from '../../../../../containers/EntityPath'
import {DetailedInvestigationsViewContext} from '../../../../../contexts/detailedView'
import {useAppSelector} from '../../../../../hooks/react-redux'
import {
  getFullPath,
  getPipelineBatchIdFromBuildId,
  getPipelineIdFromBuildId,
  getPipelineJobIdFromBuildId,
} from '../../../../../selectors'
import type {BuildId} from '../../../../../types'
import {
  getProjectBuildTypeFilter,
  toBuildId,
  toBuildTypeId,
  toProjectId,
} from '../../../../../types'
import BuildNumberContainer from '../../../../common/BuildNumber/BuildNumber.container'
import TruncateHtml from '../../../../common/TruncateHtml/TruncateHtml'
import {TreeEntityType} from '../../Tests.types'
import {trimAndRemoveColon} from '../../Tests.utils'
import type {AdvancedNode} from '../TestsTree.types'

import styles from './TestsTreeNode.module.css'

type Props = {
  dataNode: AdvancedNode
  expanded?: boolean
  buildId?: BuildId | null
}

function TestsTreeNode({dataNode, expanded, buildId}: Props) {
  const {name, testCounters, abstractParents = [], type} = dataNode
  const projectId = type === TreeEntityType.PROJECT ? toProjectId(name) : null
  let buildTypeId = type === TreeEntityType.BUILD_TYPE ? toBuildTypeId(name) : null
  if (type === TreeEntityType.BUILD && abstractParents.length > 0) {
    buildTypeId = toBuildTypeId(abstractParents[abstractParents.length - 1].name)
  }
  const nodeBuildId = type === TreeEntityType.BUILD ? toBuildId(name) : null
  const pipelineId = useAppSelector(state =>
    getPipelineIdFromBuildId(state, nodeBuildId ?? buildId),
  )
  const jobId = useAppSelector(state => getPipelineJobIdFromBuildId(state, nodeBuildId ?? buildId))
  const batchId = useAppSelector(state =>
    getPipelineBatchIdFromBuildId(state, nodeBuildId ?? buildId),
  )
  const projectBuildTypeFilter = getProjectBuildTypeFilter({projectId, buildTypeId})
  const path = useAppSelector(state => getFullPath(state, projectBuildTypeFilter))

  const fullNodePath = useMemo(() => [...abstractParents, dataNode], [abstractParents, dataNode])

  const renderEntityPath = useCallback(
    (nodePath: Array<AdvancedNode>) => {
      const abstractParentsIds = nodePath.map(el => el.name)
      const filterdPath = !pipelineId
        ? path.filter(pathItem => abstractParentsIds.includes(pathItem.id!))
        : undefined
      return (
        <EntityPath
          className={styles.entityPath}
          linkClassName={styles.entityPathLink}
          projectId={projectId}
          buildTypeId={buildTypeId}
          pipelineId={pipelineId}
          jobId={jobId}
          batchId={batchId}
          path={filterdPath}
          projectOrBuildTypeNode={{nodeType: 'all'}}
          withLeafStatusIcon={false}
          withLeafIcon
        />
      )
    },
    [batchId, buildTypeId, jobId, path, pipelineId, projectId],
  )

  const renderBuild = useMemo(
    () => (
      <BuildNumberContainer
        className={styles.buildNumber}
        buildId={nodeBuildId}
        withWarnings
        hideStar
      />
    ),
    [nodeBuildId],
  )

  const renderTestName = useMemo(() => {
    const nodeNames = fullNodePath.reduce(
      (acc, node) => ({...acc, [String(node.type)]: node.name}),
      {
        [TreeEntityType.SUITE]: '',
        [TreeEntityType.PACKAGE]: '',
        [TreeEntityType.CLASS]: '',
      },
    )

    if (type === TreeEntityType.SUITE && fullNodePath.length === 1 && nodeNames.SUITE) {
      nodeNames.SUITE = trimAndRemoveColon(nodeNames.SUITE)
    }

    if (type === TreeEntityType.CLASS && nodeNames.PACKAGE && nodeNames.CLASS) {
      nodeNames.CLASS = `.${nodeNames.CLASS}`
    }
    const testPathName = [nodeNames.SUITE, nodeNames.PACKAGE, nodeNames.CLASS]
      .filter(Boolean)
      .join('')

    return (
      <TruncateHtml
        className={styles.testPath}
        lineHeight={16}
        clamp={expanded ? null : 1}
        withToggleButton={false}
      >
        {testPathName || `<no ${type}>`}
      </TruncateHtml>
    )
  }, [expanded, fullNodePath, type])

  const renderPath = useMemo(() => {
    if (type === TreeEntityType.PROJECT || type === TreeEntityType.BUILD_TYPE) {
      return renderEntityPath(fullNodePath)
    }
    if (type === TreeEntityType.BUILD && abstractParents.length > 0) {
      return (
        <>
          {renderEntityPath(abstractParents)}
          <span className={styles.separator}>{'\u00a0/\u00a0'}</span>
          {renderBuild}
        </>
      )
    }
    return renderBuild
  }, [abstractParents, fullNodePath, renderBuild, renderEntityPath, type])

  const detailedView = useContext(DetailedInvestigationsViewContext)
  return (
    <div className={detailedView ? styles.detailedNode : styles.node}>
      {type === TreeEntityType.PROJECT ||
      type === TreeEntityType.BUILD_TYPE ||
      type === TreeEntityType.BUILD
        ? renderPath
        : renderTestName}
      {testCounters?.failed != null ? (
        <span className={styles.childrenCount}>{testCounters.failed}</span>
      ) : null}
    </div>
  )
}

export default memo(TestsTreeNode)
