import {memo} from 'react'

import {useBuildId} from '../../../../../hooks/routes'
import type {TestOccurrence} from '../../../../../services/rest'
import {EXPAND_ARROW_WIDTH, TREE_INDENT_WIDTH} from '../../../../common/Tree/Tree.consts'
import TestDetails from '../../TestDetails/TestDetails'

type Props = {
  level?: number
  testOccurrence: TestOccurrence
}

function TestsTreeLeafDetails({level, testOccurrence}: Props) {
  const buildId = useBuildId() ?? testOccurrence.build?.id
  const style = {
    paddingLeft: level != null ? `${level * TREE_INDENT_WIDTH + EXPAND_ARROW_WIDTH}px` : undefined,
  }
  return buildId != null ? (
    <div style={style}>
      <TestDetails testOccurrenceId={testOccurrence.id} buildId={buildId} />
    </div>
  ) : null
}

export default memo(TestsTreeLeafDetails)
