import Button from '@jetbrains/ring-ui-built/components/button/button'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import {memo, useCallback, useContext} from 'react'

import {restApi} from '../../../../../services/rest'
import {EXPAND_ARROW_WIDTH, TREE_INDENT_WIDTH} from '../../../../common/Tree/Tree.consts'
import type {Node} from '../../../../common/Tree/Tree.types'
import type {TestOccurrencesCounts} from '../../Tests.types'
import {TreeEntityType} from '../../Tests.types'
import {requestTestOccurrenceTreeOptions} from '../TestsTree.consts'
import {TestsTreeContext} from '../TestsTree.context'

import styles from './TestsTreeNodeFooter.module.css'

type Props = {
  level?: number
  node: Node
  type: TreeEntityType
  childrenCount: number | null | undefined
  testCounters: TestOccurrencesCounts | null | undefined
  treeLocator: string
  depth: number
}

function TestsTreeNodeFooter({
  level = 0,
  type,
  testCounters,
  childrenCount,
  node,
  treeLocator,
  depth,
}: Props) {
  const subTreeRootId = node?.value

  const {locatorInEndpoint, subTreeRootIdInLocator, getEndpoint} = useContext(TestsTreeContext)
  const [fetchTestOccurrenceSubtree, {loading}] =
    restApi.endpoints.getTestOccurrenceTree.useLazyQuery({
      selectFromResult: ({isLoading}) => ({loading: isLoading}),
    })

  const onClick = useCallback(() => {
    fetchTestOccurrenceSubtree({
      endpoint: getEndpoint(treeLocator),
      subTreeRootId: subTreeRootIdInLocator ? null : subTreeRootId,
      locator: locatorInEndpoint
        ? null
        : [treeLocator, subTreeRootIdInLocator ? `subTreeRootId:${subTreeRootId}` : null]
            .filter(Boolean)
            .join(','),
      options: requestTestOccurrenceTreeOptions,
      treeLocator,
      subTreeKey: subTreeRootId,
      depth,
    })
  }, [
    depth,
    fetchTestOccurrenceSubtree,
    getEndpoint,
    locatorInEndpoint,
    subTreeRootId,
    subTreeRootIdInLocator,
    treeLocator,
  ])

  const overallChildrenCount = type === TreeEntityType.CLASS ? testCounters?.failed : childrenCount
  const style = {paddingLeft: level * TREE_INDENT_WIDTH + EXPAND_ARROW_WIDTH}

  return overallChildrenCount != null &&
    node.children != null &&
    node.children.length < overallChildrenCount ? (
    <div style={style}>
      <Button className={styles.button} onClick={onClick} disabled={loading} inline>
        {`Show all ${overallChildrenCount} items`}
      </Button>
      {loading && <LoaderInline />}
    </div>
  ) : null
}

export default memo(TestsTreeNodeFooter)
