import classNames from 'classnames'
import {memo} from 'react'

import type {Investigation} from '../../../../../../types'

import styles from './InvestigationComment.module.css'

type Props = {
  className?: string
  investigationInCurrentScope: Investigation
}

function InvestigationComment({className, investigationInCurrentScope}: Props) {
  return investigationInCurrentScope.assignment.text !== undefined ? (
    <div
      className={classNames(className, styles.comment)}
    >{`${investigationInCurrentScope.assignment.text}`}</div>
  ) : null
}

export default memo(InvestigationComment)
