import {createContext} from 'react'

export type TestsTreeContextType = {
  getEndpoint: (locator: string) => string
  locatorInEndpoint: boolean
  subTreeRootIdInLocator?: boolean
}

const testsTreeContextDefaultValue = {
  getEndpoint: () => 'testScopes/tree',
  locatorInEndpoint: false,
  subTreeRootIdInLocator: true,
}

export const TestsTreeContext = createContext<TestsTreeContextType>(testsTreeContextDefaultValue)
