import classNames from 'classnames'
import {memo, useContext, useMemo} from 'react'

import {DetailedInvestigationsViewContext} from '../../../../../contexts/detailedView'
import {useBuildId} from '../../../../../hooks/routes'
import {getBuildType} from '../../../../../selectors'
import type {TestOccurrence} from '../../../../../services/rest'
import {getInvestigationInCurrentScope} from '../../../../common/Investigations/Investigations.selectors'
import {getActiveInvestigations} from '../../../../common/Investigations/Investigations.utils'
import TestInvestigations from '../../../../common/Investigations/TestInvestigations'
import TestMutes from '../../../../common/Mutes/TestMutes'
import TruncateHtml from '../../../../common/TruncateHtml/TruncateHtml'
import {testActionsHint} from '../../../Hints/HintItems/Hints.buildOverview'
import {useHint} from '../../../Hints/Hints.hooks'
import TestInvestigationHistoryPopup from '../../../InvestigationHistory/TestInvestigationHistoryPopup/TestInvestigationHistoryPopup'
import BuildTestActions from '../../BuildTestActions/BuildTestActions'
import CopyTestNameIconButton from '../../CopyTestNameIconButton/CopyTestNameIconButton'
import TestFlakyLabel from '../../TestFlakyLabel/TestFlakyLabel'
import TestMetadataIcon from '../../TestMetadataIcon/TestMetadataIcon'
import {
  getTestOccurrenceInvestigations,
  getTestOccurrenceMetadataCount,
  getTestOccurrenceNewFailure,
  getTestOccurrenceNextFixed,
} from '../../Tests.selectors'
import {TestStatus} from '../../Tests.types'

import InvestigationAssigneeDate from './InvestigationAssigneeDate/InvestigationAssigneeDate'
import InvestigationAssigneeName from './InvestigationAssigneeName/InvestigationAssigneeName'
import InvestigationComment from './InvestigationComment/InvestigationComment'

import styles from './TestsTreeLeaf.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  testOccurrence: TestOccurrence
  expanded?: boolean
}

function TestsTreeLeaf({testOccurrence, expanded}: Props) {
  const buildId = useBuildId() ?? testOccurrence.build?.id
  const {id, build, status, test, muted, invocations} = testOccurrence
  const {all = 0, failed = 0} = invocations?.testCounters ?? {}
  const newFailure = useAppSelector(state => getTestOccurrenceNewFailure(state, id))
  const nextFixed = useAppSelector(state => getTestOccurrenceNextFixed(state, id))
  const metadataCount = useAppSelector(state => getTestOccurrenceMetadataCount(state, id)) ?? 0
  useHint(buildId != null && testActionsHint)

  const detailedView = useContext(DetailedInvestigationsViewContext)
  const buildTypeId = build?.buildTypeId
  const projectId = useAppSelector(state => getBuildType(state, buildTypeId)?.projectId)
  const investigations = useAppSelector(state => getTestOccurrenceInvestigations(state, id))
  const activeInvestigations = useMemo(
    () => getActiveInvestigations(investigations),
    [investigations],
  )
  const investigationInCurrentScope = useAppSelector(state =>
    getInvestigationInCurrentScope(state, activeInvestigations, projectId, buildTypeId),
  )

  const onlyIcon =
    !detailedView && buildId != null ? (
      <TestInvestigations
        className={styles.testInvestigations}
        iconClassName={styles.testInvestigationsIcon}
        buildId={buildId}
        testOccurrenceId={id}
        isShowOnlyIcon
      />
    ) : null
  return buildId != null ? (
    <div className={styles.column}>
      <div className={detailedView ? styles.detailedRow : styles.row}>
        <div className={styles.leftPart}>
          <TestMutes
            className={styles.testMutes}
            iconClassName={styles.testMutesIcon}
            buildId={buildId}
            testOccurrenceId={id}
          />
          {onlyIcon}
          <TruncateHtml
            className={classNames(styles.name, {
              [styles.newFailure]: newFailure === true && status === TestStatus.FAILURE && !muted,
              [styles.fixed]: nextFixed != null,
            })}
            lineHeight={16}
            clamp={expanded ? null : 1}
            withToggleButton={false}
          >
            {test?.parsedTestName?.testNameWithParameters}
          </TruncateHtml>
          <TestFlakyLabel className={styles.flakyLabel} buildId={buildId} testId={test?.id} />
          <TestMetadataIcon
            className={styles.testMetadataIcon}
            testOccurrenceId={id}
            metadataCount={metadataCount}
          />
          <CopyTestNameIconButton iconClassName={styles.copyTestNameIcon} testOccurrenceId={id} />
        </div>
        <div className={styles.rightPart} data-hint-container-id={testActionsHint.id}>
          {all > 1 && <span className={styles.runCount}>{`${failed}/${all} runs`}</span>}
          {detailedView && investigationInCurrentScope != null && (
            <InvestigationAssigneeName investigationInCurrentScope={investigationInCurrentScope} />
          )}
          {detailedView && investigationInCurrentScope != null && (
            <InvestigationAssigneeDate investigationInCurrentScope={investigationInCurrentScope} />
          )}
          <BuildTestActions className={styles.actions} buildId={buildId} testOccurrenceId={id} />
        </div>
        <TestInvestigationHistoryPopup testOccurrenceId={id} />
      </div>
      {detailedView && investigationInCurrentScope != null && (
        <InvestigationComment
          className={styles.comment}
          investigationInCurrentScope={investigationInCurrentScope}
        />
      )}
    </div>
  ) : null
}

export default memo(TestsTreeLeaf)
