import {memo} from 'react'

import {useDistanceToNow} from '../../../../../../hooks/useTimeSelector'
import type {Investigation} from '../../../../../../types'

import styles from './InvestigationAssigneeDate.module.css'

type Props = {
  investigationInCurrentScope: Investigation
}

function InvestigationAssigneeDate({investigationInCurrentScope}: Props) {
  const date = useDistanceToNow(investigationInCurrentScope?.assignment.timestamp)
  return <span className={styles.assigneeDate}>{date}</span>
}
export default memo(InvestigationAssigneeDate)
